import "server-only";
import { readFile } from "node:fs/promises";
import path from "node:path";
import { cache } from "react";
import { breadcrumbsIn, buildTree, neighboursIn, sliceBlocks, type TocNode } from "./pure";
import type { IndexEntry, Section, Slice } from "./types";

export { sliceBlocks, type TocNode };

// generated by scripts/mafatih/extract.py from the alhassanain.org PDF
const ROOT = path.join(process.cwd(), "content", "mafatih");
const ID_RE = /^[a-z0-9-]{1,80}$/;

export const getIndex = cache(async (): Promise<IndexEntry[]> => {
  return JSON.parse(await readFile(path.join(ROOT, "index.json"), "utf8"));
});

export const getSection = cache(async (id: string): Promise<Section | null> => {
  if (!ID_RE.test(id)) return null;
  try {
    return JSON.parse(await readFile(path.join(ROOT, "s", `${id}.json`), "utf8"));
  } catch {
    return null;
  }
});

export async function getSlice(s: Slice) {
  const sec = await getSection(s.id);
  if (!sec) return null;
  return { ...sec, blocks: "h" in s ? sliceBlocks(sec.blocks, s.h) : sec.blocks };
}

export const getTree = cache(async (): Promise<TocNode[]> => buildTree(await getIndex()));

export const neighbours = async (id: string) => neighboursIn(await getIndex(), id);

export const breadcrumbs = async (id: string) => breadcrumbsIn(await getIndex(), id);
